input.proposed_solution:
The end bound was midnight at the START of `to`, so the last day was cut off. Use a half-open interval: keep `start` inclusive and compare `t < start-of-(to + 1 day)` in UTC. Added a test with 23:59:59.999 on the last day and 00:00 of the next day.

Patch (already applied in the repository snapshot):
```diff
--- a/src/range.js
+++ b/src/range.js
@@ -1,16 +1,19 @@
 // @ts-check
+
+const DAY_MS = 24 * 60 * 60 * 1000;

 /**
  * Events between `from` and `to` (both YYYY-MM-DD, UTC), inclusive of both days.
+ * The end bound is exclusive at the start of the day after `to`.
  * @param {Array<{ id: string, at: string }>} events  ISO-8601 UTC timestamps
  * @param {string} from
  * @param {string} to
  */
 export function eventsInRange(events, from, to) {
   const start = Date.parse(`${from}T00:00:00Z`);
-  const end = Date.parse(`${to}T00:00:00Z`);
+  const endExclusive = Date.parse(`${to}T00:00:00Z`) + DAY_MS;
   return events.filter((e) => {
     const t = Date.parse(e.at);
-    return t >= start && t <= end;
+    return t >= start && t < endExclusive;
   });
 }
--- a/test/range.test.js
+++ b/test/range.test.js
@@ -6,3 +6,11 @@
   const ev = [{ id: "a", at: "2026-03-01T00:00:00Z" }, { id: "b", at: "2026-02-28T23:59:59Z" }];
   assert.deepEqual(eventsInRange(ev, "2026-03-01", "2026-03-31").map((e) => e.id), ["a"]);
 });
+
+test("includes the whole last day and nothing after it", () => {
+  const ev = [
+    { id: "last", at: "2026-03-31T23:59:59.999Z" },
+    { id: "next", at: "2026-04-01T00:00:00Z" },
+  ];
+  assert.deepEqual(eventsInRange(ev, "2026-03-01", "2026-03-31").map((e) => e.id), ["last"]);
+});
```
